import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    if not example_str:
        return {}

    # Remove bracketed content, handling nested well-formed brackets iteratively
    cleaned_text = str(example_str)
    pattern = re.compile(r"\[[^\[\]]*\]")
    previous = None
    while previous != cleaned_text:
        previous = cleaned_text
        cleaned_text = pattern.sub(" ", cleaned_text)

    # Normalize whitespace
    cleaned_text = re.sub(r"\s+", " ", cleaned_text).strip()

    if not cleaned_text:
        return {}

    try:
        vectorizer = TfidfVectorizer(token_pattern=r"(?u)\b\w+\b")
        tfidf_matrix = vectorizer.fit_transform([cleaned_text])
        words = vectorizer.get_feature_names_out()
        scores = np.asarray(tfidf_matrix.toarray()[0], dtype=float)
        return {word: float(score) for word, score in zip(words, scores)}
    except ValueError:
        return {}
